// ============================================================================
// Plankalkul <-> C Runtime Bridge Declarations
// Included via `-include src/pk_bridge.h` when compiling the C translation
// units generated by `plankalkul --emit-c` (build/zuse_1942.c, build/feed_plans.c).
// ============================================================================
#ifndef PK_BRIDGE_H
#define PK_BRIDGE_H

#ifndef _GNU_SOURCE
#define _GNU_SOURCE
#endif

#include <stdint.h>

// Byte-level memory inspection primitives exposed to Plankalkul Plans (inlined in every TU)
static inline int64_t pk_c_peek_u8(int64_t ptr, int64_t idx) {
  return (int64_t)((const unsigned char *)(uintptr_t)ptr)[idx];
}
static inline int64_t pk_c_is_utf8_lead(int64_t byte_val) {
  return ((byte_val & 0xc0) != 0x80) ? 1LL : 0LL;
}

#endif // PK_BRIDGE_H
